describe('Notification Navigation', () => {
    beforeEach(() => {
        cy.visit('/'); // Visit the home page or relevant starting point
    });

    it('should navigate to the relevant content when a notification is clicked', () => {
        cy.get('.notification') // Adjust the selector based on the actual notification element
            .first() // Assuming we want to click the first notification
            .click();

        cy.url().should('include', '/relevant-content'); // Adjust the URL based on the expected navigation
        cy.get('h1').should('contain', 'Relevant Content Title'); // Adjust based on the expected content
    });

    it('should not navigate if the notification is disabled', () => {
        cy.get('.notification.disabled') // Assuming there's a class for disabled notifications
            .first()
            .click();

        cy.url().should('not.include', '/relevant-content'); // Ensure the URL does not change
        cy.get('h1').should('not.contain', 'Relevant Content Title'); // Ensure the content does not change
    });
});
